let data;try{data=JSON.parse(localStorage.getItem('office3d-v2'));if(!data||!Array.isArray(data.tasks)||!Array.isArray(data.messages))throw Error()}catch{let old;try{old=JSON.parse(localStorage.getItem('office3d-v1'))}catch{}data={tasks:old?.tasks?.map(t=>({...t,status:['Completada · demo','Rechazada'].includes(t.status)?t.status:'Versión anterior · volver a enviar'}))||[],requests:[],activity:['Nico ahora recibe y organiza las misiones del equipo.'],messages:old?.messages||[[],[],[]]}}while(data.messages.length<agents.length)data.messages.push([]);let active=0,editing=null;
const people=agents.map((a,i)=>({...a,i,pos:[...a.home],yaw:0,mode:'idle',route:[],timer:0,phase:Math.random()*5,job:null,nextBreak:20+i*14}));
const stateNames={idle:'Disponible',walking:'Caminando',receiving:'Recibiendo tu orden',planning:'Organizando el equipo',delegating:'Asignando trabajo',working:'Trabajando',supervising:'Supervisando',handoff:'Compartiendo resultados',reviewing:'Revisando la entrega',waiting:'Espera tu aprobación',eating:'Comiendo',resting:'Descansando',visiting:'En tu escritorio'};
