function save(){try{localStorage.setItem('office3d-v2',JSON.stringify(data))}catch{toast('El navegador no pudo guardar los cambios.')}}function log(s){data.activity.unshift(s);data.activity=data.activity.slice(0,80)}function toast(s){$('toast').textContent=s;$('toast').style.display='block';clearTimeout(window.tt);window.tt=setTimeout(()=>$('toast').style.display='none',3800)}
function render(){ $('team').innerHTML=people.map(p=>`<button class="agent" data-person="${p.i}"><span class="portrait" style="background:${p.color}25">${p.icon}</span><span><b>${p.name}</b><small>${p.role}</small><span class="status">● ${stateNames[p.mode]}</span></span><span class="arrow">↗</span></button>`).join('');$('request-count').textContent=data.requests.length;$('requests').innerHTML=data.requests.length?data.requests.map(r=>`<div class="request"><small>Nico · Entrega de prueba</small><b>Tu equipo terminó la propuesta</b><p>${esc(r.plan)}</p><div class="actions"><button data-approve="${r.id}">Aceptar entrega</button><button class="secondary" data-edit="${r.id}">Editar</button><button class="secondary" data-reject="${r.id}">Pedir revisión</button></div></div>`).join(''):'<div class="empty">Nico reparte el trabajo sin pedirte elegir agentes. Cuando la entrega esté lista, vendrá a presentártela.</div>';$('task-count').textContent=data.tasks.length;$('tasks').innerHTML=data.tasks.length?data.tasks.slice().reverse().map(t=>`<div class="task"><b>${esc(t.text)}</b><small>Nico · ${esc(t.status)}</small>${t.steps?`<div class="steps">${t.steps.map(s=>`<div><span>${s.status==='Completada'?'✓':s.status==='Trabajando'?'●':'○'}</span> ${agents[s.agent].name}: ${esc(s.title)} <small>${esc(s.status)}</small>${s.output?`<p>${esc(s.output)}</p>`:''}</div>`).join('')}</div>`:''}${t.result?`<p>${esc(t.result)}</p>`:''}</div>`).join(''):'<p class="footnote">Escribe lo que quieres lograr. Nico elegirá quién debe hacerlo.</p>';$('activity').innerHTML=data.activity.slice(0,15).map(x=>`<div class="task">${esc(x)}</div>`).join('');save()}
function chat(){const p=people[active];$('chat-name').textContent=p.name+' · '+p.role;$('messages').innerHTML=(data.messages[active].length?data.messages[active]:[{text:active===0?'Dime qué quieres lograr. Recibiré tu orden, elegiré a los agentes y revisaré su entrega.':'Nico organiza mis encargos. Si escribes una misión aquí, se la pasaré para que coordine el trabajo.'}]).map(m=>`<div class="message ${m.user?'user':''}">${esc(m.text)}</div>`).join('');$('messages').scrollTop=$('messages').scrollHeight;const busy=p.mode!=='idle';$('eat').disabled=busy;$('rest').disabled=busy;$('call').disabled=busy}
function openChat(i){active=i;chat();$('chat').showModal()}
function route(p,target,cb){p.mode='walking';p.timer=0;p.route=[[0,p.pos[1]],[0,target[1]],[...target]].filter((q,i,arr)=>i===0||Math.hypot(q[0]-arr[i-1][0],q[1]-arr[i-1][1])>.01);p.after=cb;render()}
function setMode(p,m,seconds=0){p.mode=m;p.timer=seconds;render()}
function announce(s){$('scene-status').textContent=s;log(s);render()}
function choosePlan(text){
 const s=text.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
 const full=/(crear|crea|desarroll|constru|implement|hacer|quiero|proyecto).*(sistema|aplicacion|app\b|software|plataforma|inventario|web|proyecto)/.test(s)||/sistema de |aplicacion de |proyecto de software/.test(s);
 const bug=/error|bug|fallo|corrige|corregir|depur|arregla/.test(s),db=/base de datos|sql|consulta|tablas|entidad|datos|persistencia/.test(s);
 const arch=/arquitectura|arquitecto|componentes|estructura del sistema|diseno tecnico/.test(s);
 const req=/requisito|historias de usuario|casos de uso|investig|busca|compar|analiz|informacion|idea/.test(s);
 const doc=/document|manual|presenta|ppt|informe|redact|escrib|propuesta/.test(s);
 const dev=/program|codigo|implement|funcion|api|backend|frontend|desarroll/.test(s),qa=/prueba|test|calidad|validar|verific/.test(s);
 const chosen=new Set();if(full){[1,3,5,4,6,2].forEach(i=>chosen.add(i))}else{
 if(req)chosen.add(1);if(arch)chosen.add(3);if(db)chosen.add(5);if(dev||bug)chosen.add(4);if(qa||dev||bug||db)chosen.add(6);if(doc)chosen.add(2);
 }
 const titles={0:'Organizar el plan del proyecto',1:'Definir requisitos y criterios de aceptación',3:'Diseñar la arquitectura del sistema',5:'Diseñar el modelo de datos',4:bug?'Diagnosticar y corregir el error':'Implementar las funciones del sistema',6:'Preparar pruebas y verificar requisitos',2:'Documentar la entrega técnica'};
 const ids=[1,3,5,4,6,2].filter(i=>chosen.has(i));if(!ids.length)ids.push(0);
 return ids.map(agent=>({agent,title:titles[agent],status:'Pendiente'}));
}
function send(text,i=0){const t={id:crypto.randomUUID(),text,agent:0,orchestrated:true,status:'En cola',steps:choosePlan(text),cursor:0};data.tasks.push(t);missions.push(t);data.messages[0].push({user:true,text},{text:'Recibí tu misión. Yo organizaré los encargos y te presentaré la entrega. Esta es una simulación por reglas, todavía sin IA.'});if(i!==0)data.messages[i].push({user:true,text},{text:'Pasé tu misión a Nico para que organice al equipo.'});announce('Nueva misión para Nico: '+text);startMission();toast(mission===t?'Nico viene a recibir tu orden.':'Misión en cola. Nico la recibirá al terminar la actual.')}
function startMission(){const p=people[0];if(mission||!missions.length)return;mission=missions.shift();p.job=mission;mission.status='Nico viene a recibir la orden';p.after=null;p.route=[];route(p,[-.7,10.8],()=>{p.yaw=-Math.PI/2;setMode(p,'receiving',2);announce('Nico recibe tu misión y se encarga de organizarla.')})}
