function breakTime(p,kind,automatic=false){if(p.mode!=='idle'||p.job)return;route(p,kind==='eating'?[3.5+(p.i%3)*.65,-4.65+(Math.floor(p.i/3))*.6]:[-4.65,-.7+(p.i%3)*.5],()=>{p.yaw=kind==='eating'?0:Math.PI/2;setMode(p,kind,automatic?8:12)})}
