$('new').onclick=()=>$('order').showModal();document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());$('team').onclick=e=>{const b=e.target.closest('[data-person]');if(b)openChat(+b.dataset.person)};$('order-form').onsubmit=e=>{e.preventDefault();const s=$('instruction').value.trim();if(s){send(s);$('instruction').value='';$('order').close()}};$('chat-form').onsubmit=e=>{e.preventDefault();const s=$('chat-input').value.trim();if(s){send(s,active);$('chat-input').value='';chat();$('chat').close()}};$('eat').onclick=()=>{breakTime(people[active],'eating');$('chat').close()};$('rest').onclick=()=>{breakTime(people[active],'resting');$('chat').close()};$('call').onclick=()=>{const p=people[active];if(p.mode==='idle')route(p,[-.7,10.8],()=>{p.yaw=-Math.PI/2;setMode(p,'visiting',6)});$('chat').close()};
$('requests').onclick=e=>{const b=e.target.closest('button');if(!b)return;const id=b.dataset.approve||b.dataset.reject||b.dataset.edit,r=data.requests.find(r=>r.id===id);if(!r||!mission||mission.id!==id)return;if(b.dataset.edit){editing=id;$('edit-text').value=r.plan;$('edit').showModal();return}data.requests=data.requests.filter(r=>r.id!==id);const p=people[0];if(b.dataset.approve){mission.result=r.plan;mission.status='Completada · demo';log('Aceptaste la entrega de Nico.');mission=null;p.job=null;route(p,p.home,()=>{p.yaw=0;setMode(p,'idle');p.nextBreak=35;startMission()});toast('Entrega aceptada. Nico atenderá la siguiente misión.')}else{mission.cursor=0;mission.steps.forEach(s=>{s.status='Pendiente';delete s.output});mission.status='En revisión';data.messages[0].push({text:'Revisaré la propuesta con el equipo. En esta demo se repite el recorrido de trabajo.'});announce('Nico reorganiza el trabajo para revisar la propuesta.');dispatch()}render()};$('edit-form').onsubmit=e=>{e.preventDefault();const r=data.requests.find(r=>r.id===editing),s=$('edit-text').value.trim();if(r&&s){r.plan=s;mission.result=s;log('Editaste la entrega de Nico.');render();$('edit').close()}};
